examples.template:
List {
    MonarchFavoritesList(
        items: [
        MonarchFavoriteItem({{items.0.label}}, id: {{items.0.id}}, systemImage: "rectangle.3.group", isCurrent: {{items.0.current}}),
        MonarchFavoriteItem({{items.1.label}}, id: {{items.1.id}}, systemImage: "list.bullet"),
        MonarchFavoriteItem({{items.2.label}}, id: {{items.2.id}}, systemImage: "tray"),
        ],
        onSelect: { _ in }
    )
}
.listStyle(.plain)
.monarchCanvas()
.frame(maxWidth: 256, minHeight: MonarchAccessibility.minimumHitTarget * 7)

